let maximumDifference=0,checkedMeans=0;
for(const source of snapshot.sources)for(const window of source.windows){
 if(window.rows.length!==30)throw new Error('Unexpected window size');
 const steps=window.rows.map(row=>row[0]);
 const expected=Array.from({length:30},(_,i)=>window.first+24+25*i);
 if(JSON.stringify(steps)!==JSON.stringify(expected))throw new Error('Step sequence mismatch');
 for(let c=1;c<snapshot.row_columns.length;c++){
  let mean=0,n=0;
  for(const row of window.rows){if(!row.every(Number.isFinite))throw new Error('Nonfinite value');mean+=(row[c]-mean)/++n;}
  const difference=Math.abs(mean-window.means[snapshot.row_columns[c]]);
  if(difference>1e-12)throw new Error('Mean mismatch');
  maximumDifference=Math.max(maximumDifference,difference);checkedMeans++;
 }
}
return {status:'INDEPENDENT_SELECTED_METRIC_RECOMPUTATION_PASSED',checked_means:checkedMeans,maximum_absolute_difference:maximumDifference};
